define('taoQtiItem/qtiCreator/widgets/interactions/mediaInteraction/Widget',['jquery', 'lodash', 'taoQtiItem/qtiCreator/widgets/interactions/Widget', 'taoQtiItem/qtiCreator/widgets/interactions/mediaInteraction/states/states', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/MediaInteraction'], function ($, _, Widget, states, commonRenderer) {
  var MediaInteractionWidget = _.extend(Widget.clone(), {
    initCreator: function initCreator() {
      var self = this;
      var $container = this.$original;
      var $item = $container.parents('.qti-item');
      this.registerStates(states);
      Widget.initCreator.call(this);
      $item.off('.' + this.element.serial).on('resize.' + this.element.serial, _.throttle(function (e) {
        var width = $container.innerWidth();
        if (width > 0) {
          self.element.object.attr('width', $container.innerWidth());
          self.destroyInteraction();
          self.renderInteraction();
        }
      }, 100));
    },
    destroy: function destroy() {
      var $container = this.$original;
      var $item = $container.parents('.qti-item');
      $item.off('resize.' + this.element.serial);
      Widget.destroy.call(this);
    },
    renderInteraction: function renderInteraction() {
      var $container = this.$original;
      var interaction = this.element;
      var autostart = interaction.attributes.autostart;
      interaction.attributes.autostart = false;
      if (interaction.object.attr('data') && interaction.object.attr('data').includes('taomedia://mediamanager/') && this.options.transcriptionMetadata && this.options.resourceMetadataUrl) {
        interaction.object.metaData.transcriptionUrl = this.options.resourceMetadataUrl + '?metadataUri=' + encodeURIComponent(this.options.transcriptionMetadata) + '&resourceUri=' + interaction.object.attr('data').replace('taomedia://mediamanager/', '');
      }
      commonRenderer.render.call(interaction.getRenderer(), interaction, {
        features: 'full',
        controlPlaying: false
      });
      interaction.attributes.autostart = autostart;
      if (interaction.hasClass('hide-player')) {
        $container.toggleClass('dimmed', true);
      } else {
        $container.toggleClass('dimmed', false);
      }
    },
    destroyInteraction: function destroyInteraction() {
      var interaction = this.element;
      commonRenderer.resetResponse.call(interaction.getRenderer(), interaction);
      commonRenderer.destroy.call(interaction.getRenderer(), interaction);
    }
  });
  return MediaInteractionWidget;
});
