define('taoQtiItem/qtiCreator/widgets/interactions/associateInteraction/ResponseWidget',['lodash', 'i18n', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/AssociateInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/sizeAdapter', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'taoQtiItem/qtiCreator/widgets/helpers/placeholder'], function (_, __, commonRenderer, sizeAdapter, instructionMgr, placeholder) {
  'use strict';

  var ResponseWidget = {
    create: function create(widget, responseMappingMode) {
      var interaction = widget.element;
      commonRenderer.resetResponse(interaction);
      commonRenderer.destroy(interaction);
      if (responseMappingMode) {
        instructionMgr.appendInstruction(widget.element, __('Please define association pairs and their scores below.'));
        interaction.responseMappingMode = true;
        widget.on('mappingAttributeChange', function (data) {
          if (data.key === 'defaultValue') {
            placeholder.score(widget, data.value);
          }
        });
        placeholder.score(widget);
      } else {
        instructionMgr.appendInstruction(widget.element, __('Please define the correct association pairs below.'));
      }
      commonRenderer.render(interaction);
      sizeAdapter.adaptSize(widget);
    },
    setResponse: function setResponse(interaction, response) {
      var responseDeclaration = interaction.getResponseDeclaration();
      commonRenderer.setResponse(interaction, ResponseWidget.formatResponse(response, responseDeclaration.attr('cardinality')));
      sizeAdapter.adaptSize(interaction.data('widget'));
    },
    destroy: function destroy(widget) {
      var interaction = widget.element;
      commonRenderer.resetResponse(interaction);
      commonRenderer.destroy(interaction);
      delete interaction.responseMappingMode;
      commonRenderer.renderEmptyPairs(interaction);
      sizeAdapter.adaptSize(widget);
    },
    getResponseSummary: function getResponseSummary(responseDeclaration) {
      var pairs = [],
        correctResponse = _.values(responseDeclaration.getCorrect()),
        mapEntries = responseDeclaration.getMapEntries();
      _.forEach(correctResponse, function (pair) {
        var sortedIdPair = pair.split(' ').sort(),
          sortedIdPairKey = sortedIdPair.join(' ');
        pairs[sortedIdPairKey] = {
          pair: sortedIdPair,
          correct: true,
          score: undefined
        };
      });
      _.forIn(mapEntries, function (score, pair) {
        var sortedIdPair = pair.split(' ').sort(),
          sortedIdPairKey = sortedIdPair.join(' ');
        if (!pairs[sortedIdPairKey]) {
          pairs[sortedIdPairKey] = {
            pair: sortedIdPair,
            correct: false,
            score: score
          };
        } else {
          pairs[sortedIdPairKey].score = score;
        }
      });
      return pairs;
    },
    formatResponse: function formatResponse(response, cardinality) {
      var formatedRes;
      if (cardinality === 'single') {
        formatedRes = {
          base: {
            pair: []
          }
        };
      } else {
        formatedRes = {
          list: {
            pair: []
          }
        };
      }
      _.forEach(response, function (pairString) {
        var pair = pairString.split(' ');
        if (cardinality === 'single') {
          formatedRes.base.pair = pair;
        } else {
          formatedRes.list.pair.push(pair);
        }
      });
      return formatedRes;
    },
    unformatResponse: function unformatResponse(formatedResponse) {
      var res = [];
      if (formatedResponse.list && formatedResponse.list.pair) {
        _.forEach(formatedResponse.list.pair, function (pair) {
          res.push(pair.join(' '));
        });
      } else if (formatedResponse.base && formatedResponse.base.pair) {
        res.push(formatedResponse.base.pair.join(' '));
      }
      return res;
    }
  };
  return ResponseWidget;
});
