define('taoQtiItem/qtiCreator/widgets/item/states/Active',['lodash', 'i18n', 'services/features', 'taoQtiItem/qtiCreator/helper/languages', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Active', 'tpl!taoQtiItem/qtiCreator/tpl/forms/item', 'taoQtiItem/qtiCreator/widgets/helpers/formElement', 'taoQtiItem/qtiCreator/widgets/helpers/qtiIdentifier', 'select2'], function (_, __, features, languages, stateFactory, Active, formTpl, formElement, qtiIdentifier) {
  'use strict';
  var removeInstructionClasses = ['remove-instructions', '__custom__remove-instructions'];
  var removeInstructionClass = 'remove-instructions';
  var writingModeVerticalRlClass = 'writing-mode-vertical-rl';
  var ItemStateActive = stateFactory.create(Active, function enterActiveState() {
    var _widget = this.widget;
    var item = _widget.element;
    var $form = _widget.$form;
    var areaBroker = this.widget.getAreaBroker();
    var $itemBody = _widget.$container.find('.qti-itemBody');
    var showIdentifier = features.isVisible('taoQtiItem/creator/item/property/identifier');
    var disableIdentifier = qtiIdentifier.isDisabled;
    var itemElements = [$itemBody, item];
    var itemHasClass = classes => classes.some(cls => item.hasClass(cls));
    var itemAddClass = cls => itemElements.forEach(el => el.addClass(cls));
    var itemRemoveClass = cls => itemElements.forEach(el => el.removeClass(cls));
    var itemRemoveClasses = classes => classes.forEach(itemRemoveClass);
    var toggleVerticalWritingModeByLang = lang => languages.getVerticalWritingModeByLang(lang).then(supportedVerticalMode => {
      var isSupported = supportedVerticalMode === 'vertical-rl';
      if (!isSupported && itemHasClass([writingModeVerticalRlClass])) {
        itemRemoveClasses([writingModeVerticalRlClass]);
      }
      $form.find('.writingMode-panel').toggle(isSupported);
      var isVertical = itemHasClass([writingModeVerticalRlClass]);
      $form.find('input[name="writingModeItem"][value="vertical"]').prop('checked', isVertical);
      $form.find('input[name="writingModeItem"][value="horizontal"]').prop('checked', !isVertical);
    });
    var titleFormat = '%title%';
    if (_widget.options.translation) {
      titleFormat = __('%title% - Translation (%lang%)');
    }
    var initialXmlLang = item.attr('xml:lang');
    $form.html(formTpl({
      serial: item.getSerial(),
      identifier: item.id(),
      showIdentifier,
      title: item.attr('title'),
      timeDependent: !!item.attr('timeDependent'),
      showTimeDependent: features.isVisible('taoQtiItem/creator/item/property/timeDependant'),
      removeInstructions: itemHasClass(removeInstructionClasses),
      showRemoveInstructions: true,
      'xml:lang': initialXmlLang,
      languagesList: item.data('languagesList'),
      disableIdentifier,
      translation: _widget.options.translation,
      translationStatus: _widget.options.translationStatus
    }));
    $itemBody.removeClass(writingModeVerticalRlClass);
    toggleVerticalWritingModeByLang(initialXmlLang);
    formElement.initWidget($form);
    formElement.setChangeCallbacks($form, item, {
      identifier: formElement.getAttributeChangeCallback(),
      title: function titleChange(i, title) {
        item.attr('title', title);
        areaBroker.getTitleArea().text(titleFormat.replace('%title%', item.attr('title')).replace('%lang%', _widget.options.translationLanguageCode));
      },
      timeDependent: formElement.getAttributeChangeCallback(),
      removeInstructions(i, value) {
        if (value) {
          itemAddClass(removeInstructionClass);
        } else {
          itemRemoveClasses(removeInstructionClasses);
        }
      },
      'xml:lang': function langChange(i, lang) {
        item.attr('xml:lang', lang);
        languages.isRTLbyLanguageCode(lang).then(isRTL => {
          if (isRTL) {
            item.bdy.attr('dir', 'rtl');
            $itemBody.attr('dir', 'rtl');
          } else {
            item.bdy.removeAttr('dir');
            $itemBody.removeAttr('dir');
          }
          $itemBody.trigger('item-dir-changed');
        });
        toggleVerticalWritingModeByLang(lang).then(() => {
          $itemBody.trigger('item-writing-mode-changed');
        });
      },
      translationStatus(i, status) {
        _widget.options.translationStatus = status;
      },
      writingModeItem(i, mode) {
        if (mode === 'vertical') {
          item.addClass(writingModeVerticalRlClass);
        } else {
          itemRemoveClasses([writingModeVerticalRlClass]);
        }
        $itemBody.trigger('item-writing-mode-changed');
      }
    });
    var $selectBox = $form.find('select');
    $selectBox.select2({
      dropdownAutoWidth: true,
      width: 'resolve',
      minimumResultsForSearch: -1,
      formatSelection: data => {
        if (data.css) {
          return "<span class=\"".concat(data.css, "\">").concat(data.text, "</span>");
        }
        return data.text;
      }
    });
  }, _.noop);
  return ItemStateActive;
});
