define('taoQtiItem/qtiCreator/widgets/interactions/extendedTextInteraction/states/Custom',['lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/helpers/stringResponse', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Custom', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/ExtendedTextInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/answerState'], function (_, __, stringResponseHelper, stateFactory, Custom, renderer, instructionMgr, answerState) {
  'use strict';

  function start() {
    var interaction = this.widget.element;
    var response = interaction.getResponseDeclaration();
    var correctResponse = stringResponseHelper.getCorrectResponse(response);
    renderer.enable(interaction);
    renderer.setText(interaction, correctResponse);
    instructionMgr.appendInstruction(interaction, __('Please type the correct response below.'));
    this.widget.$container.on('responseChange.qti-widget', function () {
      stringResponseHelper.setCorrectResponse(response, renderer.getResponse(interaction).base.string);
    });
  }
  function exit() {
    answerState.createOutcomeScore(this.widget);
    var interaction = this.widget.element;
    renderer.clearText(interaction);
    var response = this.widget.element.getResponseDeclaration();
    stringResponseHelper.rewriteCorrectResponse(response);
    instructionMgr.removeInstructions(this.widget.element);
    this.widget.$container.off('responseChange.qti-widget');
  }
  return stateFactory.create(Custom, start, exit);
});
